//! `PUT /notes/{id}` and `DELETE /notes/{id}`.

use axum::extract::State;
use axum::http::StatusCode;
use axum::routing::put;
use axum::{Json, Router};

use crate::error::{ApiError, ApiResult};
use crate::note::{Note, NoteId, NoteInput};
use crate::store::{self, Db};

pub fn routes() -> Router<Db> {
    Router::new().route("/notes/{id}", put(replace).delete(remove))
}

/// Full replacement: an omitted `body` or `tags` becomes `""` or `[]`.
async fn replace(State(db): State<Db>, id: NoteId, input: NoteInput) -> ApiResult<Json<Note>> {
    db.call(move |conn| store::crud::update(conn, id, &input))
        .await?
        .map(Json)
        .ok_or(ApiError::NotFound)
}

async fn remove(State(db): State<Db>, id: NoteId) -> ApiResult<StatusCode> {
    if db.call(move |conn| store::crud::delete(conn, id)).await? {
        Ok(StatusCode::NO_CONTENT)
    } else {
        Err(ApiError::NotFound)
    }
}

//! Request extractors shared by the handlers.
//!
//! - [`NoteInput`] reads and validates a `{title, body?, tags?}` JSON body. It does not require a
//!   `Content-Type` header, and every failure is a 400 with a JSON error body.
//! - [`NoteId`] reads the `{id}` path parameter; anything but a positive integer is a 404.

use axum::body::Bytes;
use axum::extract::{FromRequest, FromRequestParts, Path, Request};
use axum::http::request::Parts;

use crate::error::ApiError;
use crate::note::{NoteId, NoteInput};

impl<S: Send + Sync> FromRequest<S> for NoteInput {
    type Rejection = ApiError;

    async fn from_request(req: Request, state: &S) -> Result<Self, Self::Rejection> {
        let bytes = Bytes::from_request(req, state)
            .await
            .map_err(|rejection| ApiError::bad_request(rejection.body_text()))?;
        Ok(NoteInput::from_json(&bytes)?)
    }
}

impl<S: Send + Sync> FromRequestParts<S> for NoteId {
    type Rejection = ApiError;

    async fn from_request_parts(parts: &mut Parts, state: &S) -> Result<Self, Self::Rejection> {
        let Path(raw) = Path::<String>::from_request_parts(parts, state)
            .await
            .map_err(|_| ApiError::NotFound)?;
        NoteId::parse(&raw).ok_or(ApiError::NotFound)
    }
}

//! `GET /notes` with the `tag`, `q`, `after` and `limit` query parameters.

use axum::extract::{Query, State};
use axum::routing::get;
use axum::{Json, Router};
use serde::Serialize;

use crate::error::{ApiError, ApiResult};
use crate::note::Note;
use crate::store::list::ListFilter;
use crate::store::{self, Db};

/// Largest accepted (and default) `limit`.
pub const MAX_LIMIT: u32 = 100;

pub fn routes() -> Router<Db> {
    Router::new().route("/notes", get(list))
}

#[derive(Serialize)]
struct NoteList {
    notes: Vec<Note>,
}

async fn list(
    State(db): State<Db>,
    query: Result<Query<Vec<(String, String)>>, axum::extract::rejection::QueryRejection>,
) -> ApiResult<Json<NoteList>> {
    let Query(pairs) = query.map_err(|rejection| ApiError::bad_request(rejection.body_text()))?;
    let filter = parse_filter(pairs)?;
    let notes = db
        .call(move |conn| store::list::list(conn, &filter))
        .await?;
    Ok(Json(NoteList { notes }))
}

/// Builds a [`ListFilter`] from decoded query pairs. Unknown parameters are ignored; when a
/// parameter is repeated, the last value wins.
fn parse_filter(pairs: Vec<(String, String)>) -> ApiResult<ListFilter> {
    let mut filter = ListFilter {
        tag: None,
        q: None,
        after: None,
        limit: MAX_LIMIT,
    };
    for (key, value) in pairs {
        match key.as_str() {
            "tag" => filter.tag = Some(value),
            "q" => filter.q = Some(value),
            "after" => {
                filter.after = Some(
                    parse_after(&value)
                        .ok_or_else(|| ApiError::bad_request("after must be an integer"))?,
                );
            }
            "limit" => {
                filter.limit = parse_limit(&value).ok_or_else(|| {
                    ApiError::bad_request(format!("limit must be an integer from 1 to {MAX_LIMIT}"))
                })?;
            }
            _ => {}
        }
    }
    Ok(filter)
}

/// A decimal integer with an optional leading `-` (no `+`, no whitespace).
fn parse_after(s: &str) -> Option<i64> {
    let digits = s.strip_prefix('-').unwrap_or(s);
    if digits.is_empty() || !digits.bytes().all(|b| b.is_ascii_digit()) {
        return None;
    }
    s.parse().ok()
}

/// Plain decimal digits denoting an integer in `1..=MAX_LIMIT`.
fn parse_limit(s: &str) -> Option<u32> {
    if s.is_empty() || !s.bytes().all(|b| b.is_ascii_digit()) {
        return None;
    }
    s.parse().ok().filter(|n| (1..=MAX_LIMIT).contains(n))
}

#[cfg(test)]
mod tests {
    use super::*;

    fn pairs(items: &[(&str, &str)]) -> Vec<(String, String)> {
        items
            .iter()
            .map(|(k, v)| (k.to_string(), v.to_string()))
            .collect()
    }

    #[test]
    fn defaults() {
        let filter = parse_filter(vec![]).unwrap();
        assert_eq!(
            filter,
            ListFilter {
                tag: None,
                q: None,
                after: None,
                limit: MAX_LIMIT
            }
        );
    }

    #[test]
    fn reads_every_parameter() {
        let filter = parse_filter(pairs(&[
            ("tag", "work"),
            ("q", "Hi there"),
            ("after", "3"),
            ("limit", "7"),
            ("other", "ignored"),
        ]))
        .unwrap();
        assert_eq!(
            filter,
            ListFilter {
                tag: Some("work".into()),
                q: Some("Hi there".into()),
                after: Some(3),
                limit: 7
            }
        );
    }

    #[test]
    fn parses_limit() {
        assert_eq!(parse_limit("1"), Some(1));
        assert_eq!(parse_limit("100"), Some(100));
        assert_eq!(parse_limit("010"), Some(10));
        for bad in [
            "",
            "0",
            "101",
            "-1",
            "+5",
            "1.5",
            "abc",
            " 5",
            "99999999999",
        ] {
            assert_eq!(parse_limit(bad), None, "{bad:?}");
        }
    }

    #[test]
    fn parses_after() {
        assert_eq!(parse_after("0"), Some(0));
        assert_eq!(parse_after("42"), Some(42));
        assert_eq!(parse_after("-3"), Some(-3));
        for bad in ["", "-", "+1", "1.0", "abc", " 1", "99999999999999999999"] {
            assert_eq!(parse_after(bad), None, "{bad:?}");
        }
    }

    #[test]
    fn rejects_invalid_numbers() {
        assert!(parse_filter(pairs(&[("limit", "0")])).is_err());
        assert!(parse_filter(pairs(&[("after", "x")])).is_err());
    }
}

//! HTTP handlers, one submodule per feature. Each submodule exposes `routes()`, merged in
//! [`crate::app::router`]. Several features may register different methods on the same path
//! (e.g. `GET` and `POST /notes`); axum merges them, and answers other methods with 405.

pub mod crud;
pub mod extract;
pub mod list;
pub mod notes;
pub mod stats;

//! `POST /notes` and `GET /notes/{id}`.

use axum::extract::State;
use axum::http::StatusCode;
use axum::routing::{get, post};
use axum::{Json, Router};

use crate::error::{ApiError, ApiResult};
use crate::note::{Note, NoteId, NoteInput};
use crate::store::{self, Db};

pub fn routes() -> Router<Db> {
    Router::new()
        .route("/notes", post(create))
        .route("/notes/{id}", get(fetch))
}

async fn create(State(db): State<Db>, input: NoteInput) -> ApiResult<(StatusCode, Json<Note>)> {
    let note = db
        .call(move |conn| store::notes::insert(conn, &input))
        .await?;
    Ok((StatusCode::CREATED, Json(note)))
}

async fn fetch(State(db): State<Db>, id: NoteId) -> ApiResult<Json<Note>> {
    db.call(move |conn| store::notes::get(conn, id))
        .await?
        .map(Json)
        .ok_or(ApiError::NotFound)
}

//! `GET /stats` and `GET /tags`.

use std::collections::BTreeMap;

use axum::extract::State;
use axum::routing::get;
use axum::{Json, Router};
use serde::Serialize;

use crate::error::ApiResult;
use crate::store::stats::TagCount;
use crate::store::{self, Db};

pub fn routes() -> Router<Db> {
    Router::new()
        .route("/stats", get(stats))
        .route("/tags", get(tags))
}

/// `{"notes": <count>, "tags": {"<tag>": <count>, ...}}`, tags in ascending order.
#[derive(Debug, Serialize)]
struct StatsResponse {
    notes: i64,
    tags: BTreeMap<String, i64>,
}

/// `{"tags": [{"tag": "<tag>", "count": <n>}, ...]}`, by count descending, then tag ascending.
#[derive(Debug, Serialize)]
struct TagsResponse {
    tags: Vec<TagCount>,
}

async fn stats(State(db): State<Db>) -> ApiResult<Json<StatsResponse>> {
    let stats = db.call(store::stats::stats).await?;
    Ok(Json(StatsResponse {
        notes: stats.notes,
        tags: stats
            .tags
            .into_iter()
            .map(|TagCount { tag, count }| (tag, count))
            .collect(),
    }))
}

async fn tags(State(db): State<Db>) -> ApiResult<Json<TagsResponse>> {
    let tags = db.call(|conn| store::stats::tag_counts(conn)).await?;
    Ok(Json(TagsResponse { tags }))
}

//! Router assembly and the server loop.

use axum::Router;
use axum::routing::get;
use tokio::net::TcpListener;

use crate::api;
use crate::error::ApiError;
use crate::store::Db;

/// Builds the application: every feature's routes, plus JSON 404 and 405 fallbacks.
pub fn router(db: Db) -> Router {
    Router::new()
        .route("/health", get(health))
        .merge(api::notes::routes())
        .merge(api::crud::routes())
        .merge(api::list::routes())
        .merge(api::stats::routes())
        .fallback(async || ApiError::NotFound)
        .method_not_allowed_fallback(async || ApiError::MethodNotAllowed)
        .with_state(db)
}

async fn health() -> &'static str {
    "ok"
}

/// Serves `router` on `listener` until Ctrl-C or SIGTERM, then drains in-flight requests.
pub async fn serve(listener: TcpListener, router: Router) -> std::io::Result<()> {
    axum::serve(listener, router)
        .with_graceful_shutdown(shutdown_signal())
        .await
}

async fn shutdown_signal() {
    let ctrl_c = async {
        if let Err(err) = tokio::signal::ctrl_c().await {
            tracing::warn!(error = %err, "cannot listen for Ctrl-C");
            std::future::pending::<()>().await;
        }
    };

    #[cfg(unix)]
    let terminate = async {
        use tokio::signal::unix::{SignalKind, signal};
        match signal(SignalKind::terminate()) {
            Ok(mut sigterm) => {
                sigterm.recv().await;
            }
            Err(err) => {
                tracing::warn!(error = %err, "cannot listen for SIGTERM");
                std::future::pending::<()>().await;
            }
        }
    };
    #[cfg(not(unix))]
    let terminate = std::future::pending::<()>();

    tokio::select! {
        () = ctrl_c => {}
        () = terminate => {}
    }
    tracing::info!("shutting down");
}

//! The error type returned by handlers, rendered as `{"error": "<message>"}`.

use axum::Json;
use axum::http::StatusCode;
use axum::response::{IntoResponse, Response};
use serde_json::json;

use crate::note::InvalidNote;
use crate::store::StoreError;

#[derive(Debug, thiserror::Error)]
pub enum ApiError {
    #[error("{0}")]
    BadRequest(String),
    #[error("not found")]
    NotFound,
    #[error("method not allowed")]
    MethodNotAllowed,
    #[error(transparent)]
    Store(#[from] StoreError),
}

impl ApiError {
    pub fn bad_request(message: impl Into<String>) -> Self {
        Self::BadRequest(message.into())
    }

    pub fn status(&self) -> StatusCode {
        match self {
            Self::BadRequest(_) => StatusCode::BAD_REQUEST,
            Self::NotFound => StatusCode::NOT_FOUND,
            Self::MethodNotAllowed => StatusCode::METHOD_NOT_ALLOWED,
            Self::Store(_) => StatusCode::INTERNAL_SERVER_ERROR,
        }
    }
}

impl From<InvalidNote> for ApiError {
    fn from(err: InvalidNote) -> Self {
        Self::BadRequest(err.to_string())
    }
}

impl IntoResponse for ApiError {
    fn into_response(self) -> Response {
        let message = match &self {
            Self::Store(err) => {
                // Details stay in the log; clients get a generic message.
                tracing::error!(error = %err, "request failed");
                "internal server error".to_owned()
            }
            other => other.to_string(),
        };
        (self.status(), Json(json!({ "error": message }))).into_response()
    }
}

pub type ApiResult<T> = Result<T, ApiError>;

//! A small notes store over HTTP, backed by SQLite.
//!
//! Layout (one feature per file so features can be developed independently):
//! - [`note`]: the domain model and input validation.
//! - [`store`]: the SQLite pool, schema, and data access, one submodule per feature.
//! - [`api`]: HTTP handlers, one submodule per feature, each exposing `routes()`.
//! - [`app`]: assembles the router and runs the server.

pub mod api;
pub mod app;
pub mod error;
pub mod note;
pub mod store;

//! `app <port>`: serves the notes API on `127.0.0.1:<port>`, storing data in the SQLite database
//! at `$NOTES_DB`.

use std::net::{Ipv4Addr, SocketAddr};
use std::process::ExitCode;

use anyhow::{Context, bail};
use tokio::net::TcpListener;
use tracing_subscriber::EnvFilter;

use notes::app;
use notes::store::Db;

#[tokio::main]
async fn main() -> ExitCode {
    tracing_subscriber::fmt()
        .with_env_filter(EnvFilter::try_from_default_env().unwrap_or_else(|_| "info".into()))
        .with_writer(std::io::stderr)
        .init();

    match run().await {
        Ok(()) => ExitCode::SUCCESS,
        Err(err) => {
            tracing::error!("{err:#}");
            ExitCode::FAILURE
        }
    }
}

async fn run() -> anyhow::Result<()> {
    let mut args = std::env::args().skip(1);
    let (Some(port), None) = (args.next(), args.next()) else {
        bail!("usage: app <port>");
    };
    let port: u16 = port
        .parse()
        .with_context(|| format!("invalid port {port:?}"))?;
    let db_path = std::env::var_os("NOTES_DB").context("NOTES_DB is not set")?;

    let db = Db::open(&db_path)
        .with_context(|| format!("cannot open database {}", db_path.to_string_lossy()))?;

    let addr = SocketAddr::from((Ipv4Addr::LOCALHOST, port));
    let listener = TcpListener::bind(addr)
        .await
        .with_context(|| format!("cannot listen on {addr}"))?;
    tracing::info!(%addr, "listening");

    app::serve(listener, app::router(db)).await?;
    Ok(())
}

//! The note domain model and the validation rules for client input.
//!
//! Everything here is independent of HTTP and SQL so that it can be shared by every endpoint
//! (`POST /notes` and `PUT /notes/{id}` accept the same body) and unit-tested in isolation.

use std::collections::BTreeSet;
use std::fmt;

use serde::Serialize;
use serde_json::{Map, Value};

/// Maximum length of a title, in characters, after trimming.
pub const TITLE_MAX_CHARS: usize = 200;
/// Maximum length of a tag, in characters.
pub const TAG_MAX_CHARS: usize = 32;

/// A stored note, as returned to clients.
#[derive(Debug, Clone, PartialEq, Eq, Serialize)]
pub struct Note {
    pub id: i64,
    pub title: String,
    pub body: String,
    /// Unique and sorted ascending.
    pub tags: Vec<String>,
}

/// The identifier of a note: always a positive integer.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub struct NoteId(i64);

impl NoteId {
    /// Parses a path segment such as `"42"`. Only plain decimal digits denoting a positive `i64`
    /// are accepted (no sign, no whitespace).
    pub fn parse(s: &str) -> Option<Self> {
        if s.is_empty() || !s.bytes().all(|b| b.is_ascii_digit()) {
            return None;
        }
        s.parse::<i64>().ok().and_then(Self::new)
    }

    /// Wraps a raw id, returning `None` unless it is positive.
    pub fn new(id: i64) -> Option<Self> {
        (id > 0).then_some(Self(id))
    }

    pub fn get(self) -> i64 {
        self.0
    }
}

impl fmt::Display for NoteId {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        self.0.fmt(f)
    }
}

/// Why a request body was rejected. The `Display` text is sent to the client.
#[derive(Debug, Clone, PartialEq, Eq, thiserror::Error)]
pub enum InvalidNote {
    #[error("request body is not valid JSON")]
    NotJson,
    #[error("request body must be a JSON object")]
    NotObject,
    #[error("title is required")]
    MissingTitle,
    #[error("title must be a string of 1 to {TITLE_MAX_CHARS} characters")]
    InvalidTitle,
    #[error("body must be a string")]
    InvalidBody,
    #[error("tags must be an array of strings")]
    TagsNotArray,
    #[error("each tag must be 1 to {TAG_MAX_CHARS} characters from a-z, 0-9 and -")]
    InvalidTag,
}

/// A validated, normalized note body (`{title, body?, tags?}`), ready to be stored.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct NoteInput {
    /// Trimmed of leading and trailing spaces.
    pub title: String,
    pub body: String,
    /// Deduplicated and sorted ascending.
    pub tags: Vec<String>,
}

impl NoteInput {
    /// Parses and validates a raw JSON request body. Unknown fields are ignored.
    pub fn from_json(bytes: &[u8]) -> Result<Self, InvalidNote> {
        match serde_json::from_slice::<Value>(bytes).map_err(|_| InvalidNote::NotJson)? {
            Value::Object(map) => Self::from_object(&map),
            _ => Err(InvalidNote::NotObject),
        }
    }

    fn from_object(map: &Map<String, Value>) -> Result<Self, InvalidNote> {
        let title = match map.get("title") {
            None => return Err(InvalidNote::MissingTitle),
            Some(Value::String(s)) => normalize_title(s)?,
            Some(_) => return Err(InvalidNote::InvalidTitle),
        };
        let body = match map.get("body") {
            None => String::new(),
            Some(Value::String(s)) => s.clone(),
            Some(_) => return Err(InvalidNote::InvalidBody),
        };
        let tags = match map.get("tags") {
            None => Vec::new(),
            Some(Value::Array(items)) => normalize_tags(items)?,
            Some(_) => return Err(InvalidNote::TagsNotArray),
        };
        Ok(Self { title, body, tags })
    }
}

fn normalize_title(raw: &str) -> Result<String, InvalidNote> {
    let title = raw.trim_matches(' ');
    let len = title.chars().count();
    if (1..=TITLE_MAX_CHARS).contains(&len) {
        Ok(title.to_owned())
    } else {
        Err(InvalidNote::InvalidTitle)
    }
}

fn normalize_tags(items: &[Value]) -> Result<Vec<String>, InvalidNote> {
    let mut tags = BTreeSet::new();
    for item in items {
        let Value::String(tag) = item else {
            return Err(InvalidNote::TagsNotArray);
        };
        if !is_valid_tag(tag) {
            return Err(InvalidNote::InvalidTag);
        }
        tags.insert(tag.as_str());
    }
    Ok(tags.into_iter().map(str::to_owned).collect())
}

/// Whether `tag` is 1–32 characters from `a-z`, `0-9` and `-`.
pub fn is_valid_tag(tag: &str) -> bool {
    (1..=TAG_MAX_CHARS).contains(&tag.len())
        && tag
            .bytes()
            .all(|b| b.is_ascii_lowercase() || b.is_ascii_digit() || b == b'-')
}

#[cfg(test)]
mod tests {
    use super::*;

    fn parse(json: &str) -> Result<NoteInput, InvalidNote> {
        NoteInput::from_json(json.as_bytes())
    }

    #[test]
    fn minimal_note_gets_defaults() {
        let input = parse(r#"{"title":"first"}"#).unwrap();
        assert_eq!(
            input,
            NoteInput {
                title: "first".into(),
                body: String::new(),
                tags: vec![]
            }
        );
    }

    #[test]
    fn title_is_trimmed_and_tags_are_normalized() {
        let input =
            parse(r#"{"title":"  second  ","body":"text","tags":["work","b-2","work"]}"#).unwrap();
        assert_eq!(input.title, "second");
        assert_eq!(input.body, "text");
        assert_eq!(input.tags, ["b-2", "work"]);
    }

    #[test]
    fn rejects_malformed_bodies() {
        assert_eq!(parse(r#"{"title": "#), Err(InvalidNote::NotJson));
        assert_eq!(parse(""), Err(InvalidNote::NotJson));
        assert_eq!(parse("[]"), Err(InvalidNote::NotObject));
        assert_eq!(parse(r#""title""#), Err(InvalidNote::NotObject));
    }

    #[test]
    fn validates_title() {
        assert_eq!(parse("{}"), Err(InvalidNote::MissingTitle));
        assert_eq!(parse(r#"{"title":"   "}"#), Err(InvalidNote::InvalidTitle));
        assert_eq!(parse(r#"{"title":""}"#), Err(InvalidNote::InvalidTitle));
        assert_eq!(parse(r#"{"title":5}"#), Err(InvalidNote::InvalidTitle));
        assert_eq!(parse(r#"{"title":null}"#), Err(InvalidNote::InvalidTitle));

        let max = "é".repeat(TITLE_MAX_CHARS);
        assert!(parse(&format!(r#"{{"title":" {max} "}}"#)).is_ok());
        let too_long = "a".repeat(TITLE_MAX_CHARS + 1);
        assert_eq!(
            parse(&format!(r#"{{"title":"{too_long}"}}"#)),
            Err(InvalidNote::InvalidTitle)
        );
    }

    #[test]
    fn validates_body() {
        assert_eq!(
            parse(r#"{"title":"x","body":3}"#),
            Err(InvalidNote::InvalidBody)
        );
        assert_eq!(
            parse(r#"{"title":"x","body":null}"#),
            Err(InvalidNote::InvalidBody)
        );
    }

    #[test]
    fn validates_tags() {
        assert_eq!(
            parse(r#"{"title":"x","tags":"a"}"#),
            Err(InvalidNote::TagsNotArray)
        );
        assert_eq!(
            parse(r#"{"title":"x","tags":[1]}"#),
            Err(InvalidNote::TagsNotArray)
        );
        assert_eq!(
            parse(r#"{"title":"x","tags":["Bad"]}"#),
            Err(InvalidNote::InvalidTag)
        );
        assert_eq!(
            parse(r#"{"title":"x","tags":[""]}"#),
            Err(InvalidNote::InvalidTag)
        );
        assert_eq!(
            parse(r#"{"title":"x","tags":["a b"]}"#),
            Err(InvalidNote::InvalidTag)
        );
        assert!(is_valid_tag(&"a".repeat(TAG_MAX_CHARS)));
        assert!(!is_valid_tag(&"a".repeat(TAG_MAX_CHARS + 1)));
        assert!(is_valid_tag("a-0"));
    }

    #[test]
    fn parses_note_ids() {
        assert_eq!(NoteId::parse("7").map(NoteId::get), Some(7));
        assert_eq!(NoteId::parse("007").map(NoteId::get), Some(7));
        for bad in [
            "",
            "0",
            "-1",
            "+1",
            "abc",
            " 1",
            "1.0",
            "99999999999999999999",
        ] {
            assert_eq!(NoteId::parse(bad), None, "{bad:?}");
        }
    }
}

//! Updating and deleting notes (`crud` branch).

use rusqlite::{Connection, TransactionBehavior, params};

use super::Result;
use super::notes::insert_tags;
use crate::note::{Note, NoteId, NoteInput};

/// Replaces the title, body and tags of a note. Returns the updated note, or `None` if no note
/// has this id.
pub fn update(conn: &mut Connection, id: NoteId, input: &NoteInput) -> Result<Option<Note>> {
    let tx = conn.transaction_with_behavior(TransactionBehavior::Immediate)?;
    let updated = tx
        .prepare_cached("UPDATE notes SET title = ?2, body = ?3 WHERE id = ?1")?
        .execute(params![id.get(), input.title, input.body])?;
    if updated == 0 {
        // Nothing changed; dropping `tx` rolls back.
        return Ok(None);
    }
    tx.prepare_cached("DELETE FROM note_tags WHERE note_id = ?1")?
        .execute([id.get()])?;
    insert_tags(&tx, id.get(), &input.tags)?;
    tx.commit()?;

    Ok(Some(Note {
        id: id.get(),
        title: input.title.clone(),
        body: input.body.clone(),
        tags: input.tags.clone(),
    }))
}

/// Deletes a note and its tags. Returns whether a note with this id existed.
pub fn delete(conn: &Connection, id: NoteId) -> Result<bool> {
    // A single statement is atomic; `ON DELETE CASCADE` removes the note's tags with it.
    let deleted = conn
        .prepare_cached("DELETE FROM notes WHERE id = ?1")?
        .execute([id.get()])?;
    Ok(deleted > 0)
}

